package Collections_Framework.MAP;import java.util.*;public class LINKEDHASHMAP {    public static void main(String[] args) {        Map<Integer,String> map=new LinkedHashMap<>();        map.put(1,"aman sharma");        map.put(7,"aman yadav");        map.put(22,"aman varshney");        map.put(4,"pradeep JI");        for(int i: map.keySet()) {            System.out.println(i+" "+map.get(i));        }        System.out.println(map.containsKey(1));        System.out.println(map.get(1));        map.forEach((k,v)-> System.out.println(k+":"+v));    }}//insertion order preserved nahi h..kesi bhi order me aa jayega//order maintained ke liye linkedhashmap use karenge